// This is just a test, and I haven't been working with GLSL (OpenGL Shading Language) for long.
// Fractal Neon Shader by melcom (www.melcom-music.de)

#define PI 3.14159265359

// Erzeugt eine Neonfarben-Palette basierend auf dem Parameter t / Creates a neon color palette based on the parameter t
vec3 neonPalette(float t) {
    return vec3(sin(PI * t), sin(PI * t + 2.0 * PI / 3.0), sin(PI * t + 4.0 * PI / 3.0));
}

// Berechnet die Fraktale / Calculates the fractals
float fractal(vec2 p) {
    float iter = 0.0;
    for (int i = 0; i < 8; i++) {
        p = abs(p) / dot(p, p) - 0.5;
        iter += length(p);
    }
    return iter;
}

// Hauptfunktion für das Bild / Main image function
void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = fragCoord.xy / iResolution.xy; // Normierung der UV-Koordinaten / Normalize UV coordinates
    vec2 pos = uv * 2.0 - 1.0; // Konvertierung der UV-Koordinaten in den Bereich [-1, 1] / Convert UV coordinates to the range [-1, 1]
    pos.x *= iResolution.x / iResolution.y; // Skalierung basierend auf dem Seitenverhältnis / Scale based on aspect ratio

    float time = iTime; // Geschwindigkeit erhöhen / Increase speed

    // Fraktale Berechnung / Fractal calculation
    vec2 p = pos + vec2(sin(time), cos(time)) * 0.5;
    float f = fractal(p);
    vec3 color = neonPalette(f * 0.1);

    // Sinus-Scroller / Sine scroller
    float wave = sin(pos.x * 10.0 + time * 2.0) * 0.1 + cos(pos.x * 5.0 + time * 3.0) * 0.05;
    pos.y += wave;

    if (abs(pos.y) < 0.1) {
        color = neonPalette(uv.x);
    }

    fragColor = vec4(color, 1.0); // Setzen der finalen Fragmentfarbe / Setting the final fragment color
}
